package com.kynsoft.report.infrastructure.entity;
import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.util.UUID;
@Getter @Setter @Entity @Table(name="conteo_fisico_linea") public class ConteoFisicoLinea { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="conteo_id",nullable=false) private ConteoFisicoAlmacen conteo; @Column(name="almacen_finca_producto_id",nullable=false) private UUID almacenFincaProductoId; @Column(name="producto_codigo",nullable=false,length=80) private String productoCodigo; @Column(name="producto_nombre",nullable=false,length=200) private String productoNombre; @Column(name="unidad_medida",length=60) private String unidadMedida; @Column(name="existencia_teorica",nullable=false) private Double existenciaTeorica; @Column(name="existencia_fisica") private Double existenciaFisica; @Column private Double diferencia; @Column(length=500) private String observaciones; }
